from functools import singledispatch
@singledispatch
def serialize(value):
    raise TypeError(f'Unsupported type: {type(value)}')

@serialize.register
def _(value: bool):
    return 'true' if value else 'false'

@serialize.register
def _(value: int):
    return str(value)

@serialize.register
def _(value: float):
    return f'{value:.6g}'

@serialize.register
def _(value: str):
    return f'"{value}"'

@serialize.register
def _(value: list):
    return '[' + ', '.join(serialize(v) for v in value) + ']'

@serialize.register
def _(value: dict):
    pairs = ', '.join(f'{serialize(k)}: {serialize(v)}' for k, v in value.items())
    return '{' + pairs + '}'

@serialize.register
def _(value: None):
    return 'null'
